:root {
  --cream: #f2ead8;
  --parchment: #e8dcc0;
  --border-brown: #8b6f3e;
  --dark-ink: #2c1f0e;
  --mid-ink: #5a3e1b;
  --faded-ink: #7a6040;
  --accent-navy: #1e3055;
  --accent-gold: #b8860b;
  --accent-rust: #8b3a1e;
  --status-done-bg: #d4edda;
  --status-done-text: #1a5c2a;
  --status-progress-bg: #fff3cd;
  --status-progress-text: #7a5500;
  --status-pending-bg: #f8d7da;
  --status-pending-text: #7a1a20;
  --rule-line: #c4a96a;
}

.commission-card {
  background-color: var(--cream);
  border: 2px solid var(--border-brown);
  border-radius: 4px;
  width: 480px;
  padding: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  outline: 4px solid var(--parchment);
  outline-offset: -7px;
}

.card-header {
  background-color: var(--accent-navy);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 3px solid var(--accent-gold);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.shop-emblem {
  font-size: 26px;
  color: var(--accent-gold);
  line-height: 1;
}

.shop-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.shop-name {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--cream);
}

.shop-sub {
  font-size: 10px;
  color: var(--rule-line);
  letter-spacing: 0.06em;
}

.commission-badge {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.badge-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: var(--rule-line);
}

.badge-num {
  font-size: 15px;
  font-weight: 700;
  color: var(--accent-gold);
  letter-spacing: 0.06em;
}

.card-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  flex: 1;
}

.globe-spec {
  padding: 12px 14px;
  border-right: 1px solid var(--rule-line);
  width: 180px;
  flex-shrink: 0;
}

.spec-title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--faded-ink);
  margin-bottom: 8px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--rule-line);
}

.spec-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.spec-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.spec-key {
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--faded-ink);
}

.spec-val {
  font-size: 13px;
  font-weight: 700;
  color: var(--dark-ink);
}

.constellation-log {
  padding: 12px 14px;
  flex: 1;
}

.log-title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--faded-ink);
  margin-bottom: 8px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--rule-line);
}

.constellation-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.constellation-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  background-color: var(--parchment);
  border-radius: 3px;
  border-left: 3px solid var(--accent-gold);
}

.con-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--dark-ink);
  flex: 1;
}

.con-stars {
  font-size: 10px;
  color: var(--accent-gold);
  letter-spacing: 1px;
}

.con-status {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 2px 6px;
  border-radius: 10px;
}

.status-done {
  background-color: var(--status-done-bg);
  color: var(--status-done-text);
}

.status-progress {
  background-color: var(--status-progress-bg);
  color: var(--status-progress-text);
}

.status-pending {
  background-color: var(--status-pending-bg);
  color: var(--status-pending-text);
}

.card-footer {
  background-color: var(--parchment);
  border-top: 2px solid var(--rule-line);
  display: flex;
  align-items: center;
  padding: 8px 14px;
  gap: 0;
}

.footer-col {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  align-items: center;
}

.footer-label {
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--faded-ink);
}

.footer-val {
  font-size: 13px;
  font-weight: 700;
  color: var(--mid-ink);
}

.footer-price {
  color: var(--accent-rust);
  font-size: 15px;
}

.footer-divider {
  width: 1px;
  height: 30px;
  background-color: var(--rule-line);
  flex-shrink: 0;
}
